// Genshin region emblems for the Archon Quest tag, one per role, traced from the in-game emblems'
// transparency (potrace): the solid parts in the current text colour, the faint parts at lower
// opacity, as in the originals.

// A traced emblem: its faint and solid layers, in potrace's frame (tenths of a pixel of a 4x trace,
// y up), cropped to the emblem by `viewBox`.
export function Emblem({ faint, solid, viewBox, size, ...props }) {
  return (
    <svg viewBox={viewBox} fill="currentColor" aria-hidden="true" {...props}>
      <g transform={`translate(0 ${size}) scale(0.1 -0.1)`}>
        <path opacity="0.4" d={faint} />
        <path d={solid} />
      </g>
    </svg>
  );
}

